  "target_rule_id": "E03",
  "principle": {
    "instruction": "Annotate semantically atomic units rather than maximal noun phrases. For ANAT, treat a contiguous conventional regional adjective–anatomical head name as one atomic span rather than splitting or truncating it; otherwise separate independently meaningful components and exclude ordinary terminal punctuation.",
    "applies_when": "Forming the boundary of a contiguous modifier–head expression that conventionally names a single anatomical structure or region.",
    "exceptions": [
      "Keep laterality and independent directional locators separate from the conventional anatomical name.",
      "Keep numeric measurements with their units and internal separators as one span."
    ],
    "priority": 3,
    "examples": [
      "Annotate \"lumbar spine\" as one ANAT span.",
      "In \"left lumbar spine,\" annotate \"left\" separately and keep \"lumbar spine\" together.",
      "Do not include the period after an anatomical mention."
    ]
  },
  "rationale": "This narrowly prevents truncation of conventional anatomical compounds without adopting the previously unsuccessful policy of merging all anatomical noun phrases. An isolated terminal-punctuation boundary does not justify reversing the general rule that ordinary sentence punctuation is excluded."
}

