{
  "action": "REVISE",
  "target_rule_id": "E09",
  "principle": {
    "instruction": "Assign OBS-U to the observation governed by an uncertainty cue, but label an annotated uncertainty-status descriptor itself OBS-DP when the report directly asserts that descriptor as a finding attribute.",
    "applies_when": "A term such as \"indeterminate\" or \"uncertain\" directly characterizes a present finding rather than introducing a separate possible diagnosis or observation.",
    "exceptions": [
      "If the term instead scopes a separately identifiable proposed observation or diagnosis, label that scoped observation or diagnosis OBS-U."
    ],
    "priority": 9,
    "examples": [
      "In \"indeterminate opacity,\" label \"indeterminate\" OBS-DP as a directly asserted status attribute and \"opacity\" OBS-DP.",
      "In \"opacity possibly representing pneumonia,\" label \"pneumonia\" OBS-U."
    ]
  },
  "rationale": "The discrepancy recurs where \"indeterminate\" is itself a directly asserted characterization of a visible opacity. Distinguishing the asserted status descriptor from an observation placed under uncertainty prevents lexical uncertainty words from being automatically mislabeled OBS-U."
}
